    private static byte[] Block(string base64) => Convert.FromBase64String(base64);

    private static string Export(string base64, int roomId, IfcProfile version = IfcProfile.Current)
    {
        byte[] data = Block(base64);
        var geometry = ElementBuilder.BuildGeometryData(GRepParserV2.ParseCurvedSpaceBoundary(data, 0, (uint)(data.Length - 16), (uint)roomId)!)!;
        var level = new Element
        {
            Id = 900, Name = "Level", IsNativeLevel = true, SerializedFamilyId = -1, SerializedUnplacedOwnerId = -1, SerializedOwnerDbViewId = -1,
            Parameters =
            [
                new() { Id = -1007102, Definition = new Definition { Name = "LEVEL_ELEV" }, StorageType = StorageType.Double, Value = 0.0 },
                new() { Id = -1007111, StorageType = StorageType.Integer, Value = 1 },
            ],
        };
        var room = new Element
        {
            Id = roomId, CategoryId = -2000160, Category = "OST_Rooms", Name = "Room",
            Parameters =
            [
                new() { Id = -1006916, StorageType = StorageType.ElementId, Value = 900 },
                new() { Id = -1006901, StorageType = StorageType.String, Value = "1" },
            ],
            SerializedCurvedSpaceBoundary = geometry,
        };
        var info = new RevitFileInfo();
        info.Elements.Add(level);
        info.Elements.Add(room);
        string path = Path.Combine(Path.GetTempPath(), $"space-curved-{Guid.NewGuid():N}.ifc");
        try
        {
            new IfcExporter { Profile = version }.Export(info, path);
            return File.ReadAllText(path);
        }
        finally { if (File.Exists(path)) File.Delete(path); }
    }

    [Fact]
    public void ThePlanarReader_RefusesARoundWall_AndTheCurvedReaderTakesIt()
    {
        byte[] data = Block(Room9821608);
        uint size = (uint)(data.Length - 16);
        Assert.Null(GRepParserV2.ParseExactPlanarSpaceBoundary(data, 0, size, 9821608));
        var body = Assert.IsType<GRepData>(GRepParserV2.ParseCurvedSpaceBoundary(data, 0, size, 9821608));
        var geometry = ElementBuilder.BuildGeometryData(body)!;
        var node = Assert.Single(geometry.MeshNodes!);
        Assert.Equal(11, node.Faces.Count);
        Assert.Single(node.Faces, face => face.SurfaceKind != RvtIO.Geometry.Meshing.SurfaceKind.Plane);
        Assert.True(Assert.Single(geometry.BrepSolids!).IsClosed);
    }

    [Fact]
    public void ACacheOfPlanes_IsNotTheCurvedReaders()
    {
        byte[] data = Convert.FromBase64String(GRepParserV2SpaceBoundaryWeldTests.Room6957647);
        Assert.Null(GRepParserV2.ParseCurvedSpaceBoundary(data, 0, (uint)(data.Length - 16), 6957647));
    }

    [Fact]
    public void ARoomWithoutAnExtrusion_IsWrittenAsOneTriangleSet()
    {
        string ifc = Export(Room9821608, 9821608);
        Assert.Single(Regex.Matches(ifc, "#[0-9]+=IFCFACETEDBREP[(]"));
        Assert.DoesNotContain("=IFCEXTRUDEDAREASOLID(", ifc);
        Assert.Equal(56, Regex.Matches(ifc, "#[0-9]+=IFCFACE[(]").Count);
        Assert.DoesNotContain("=IFCFACEBOUND(", ifc);
        Assert.All(Regex.Matches(ifc, "#[0-9]+=IFCPOLYLOOP[(]([^)]*)[)]").Select(m => m.Groups[1].Value),
            loop => Assert.Equal(3, loop.Split(',').Length));
    }

    [Fact]
    public void TheLegacyTarget_WritesNoBodyForARoomWithARoundWall()
    {
        string ifc = Export(Room9821608, 9821608, IfcProfile.Legacy);
        Assert.Contains("=IFCSPACE(", ifc);
        Assert.DoesNotContain("=IFCFACETEDBREP(", ifc);
        Assert.DoesNotContain("=IFCEXTRUDEDAREASOLID(", ifc);
    }

    [Fact]
    public void TheCurvedBoundary_IsKeptApartFromThePlanarOne()
    {
        byte[] data = Block(Room9821608);
        var body = GRepParserV2.ParseCurvedSpaceBoundary(data, 0, (uint)(data.Length - 16), 9821608)!;
        Assert.True(body.CurvedSpaceBoundary);
        var room = new Element { Id = 9821608, CategoryId = -2000160 };
        ElementBuilder.ApplySerializedSpaceBoundaries([room], new Dictionary<uint, (int, string?)> { [9821608] = (1, "Room") },
            new Dictionary<uint, (int, GRepData?)> { [9821608] = (1, body) });
        Assert.Null(room.SerializedSpaceBoundary);
        Assert.NotNull(room.SerializedCurvedSpaceBoundary);
        Assert.Same(room.SerializedCurvedSpaceBoundary, room.SerializedSpaceBoundaryCurrent);
    }

    [Fact]
    public void ARoomWithAnExtrusion_KeepsTheLengthOfReference()
    {
        string ifc = Export(Room2795696, 2795696);
        Assert.DoesNotContain("=IFCFACETEDBREP(", ifc);
        var solid = Regex.Match(ifc, "=IFCEXTRUDEDAREASOLID[(]#[0-9]+,#[0-9]+,#[0-9]+,([^)]*)[)];");
        Assert.True(solid.Success);
        Assert.Equal(2607, double.Parse(solid.Groups[1].Value.TrimEnd('.'), System.Globalization.CultureInfo.InvariantCulture), 6);
    }
}
